1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.jspecify.annotations.Nullable;
5	import org.mapstruct.Mapper;
6	import org.mapstruct.Mapping;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
23	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
24	    @Mapping(target = "initials", expression = "java(initials(owner))")
25	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
26	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(locality(owner))")
31	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
33	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
34	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
35	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
36	    @Mapping(target = "selfLink", expression = "java(selfLink(owner))")
37	    OwnerDto toOwnerDto(Owner owner);
38	
39	    /**
40	     * Derives the owner's {@code selfLink}, the canonical relative URL of the owner formatted as
41	     * {@code '/api/owners/' + id}. Returns {@code null} when the owner or its id is absent.
42	     */
43	    default @Nullable String selfLink(@Nullable Owner owner) {
44	        if (owner == null || owner.getId() == null) {
45	            return null;
46	        }
47	        return "/api/owners/" + owner.getId();
48	    }
49	
50	    /**
51	     * The fiscal year in which a date falls, labelled by the calendar year in which the fiscal year
52	     * ends. The fiscal year starts on 1 July, so a date on or after 1 July belongs to the fiscal year
53	     * ending the following calendar year, and a date before 1 July belongs to the fiscal year ending
54	     * that calendar year.
55	     */
56	    private static int fiscalYearEnding(java.time.LocalDate date) {
57	        return date.getMonthValue() >= java.time.Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
58	    }
59	
60	    /**
61	     * Derives the owner's {@code fiscalYear} from its business-day-adjusted registrationDate, formatted
62	     * as {@code 'FY<YY>'} where YY is the last two digits of the calendar year in which the fiscal year
63	     * ends (the fiscal year starts on 1 July). Returns {@code null} when the owner has no
64	     * registrationDate.
65	     */
66	    default @Nullable String fiscalYear(@Nullable Owner owner) {
67	        if (owner == null || owner.getRegistrationDate() == null) {
68	            return null;
69	        }
70	        return String.format("FY%02d", fiscalYearEnding(owner.getRegistrationDate()) % 100);
71	    }
72	
73	    /**
74	     * Derives the owner's {@code ageBand} from its birthDate relative to the registrationDate:
75	     * {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and {@code SENIOR} when 65 or older.
76	     * Returns {@code null} when the owner has no birthDate or no registrationDate.
77	     */
78	    default OwnerDto.@Nullable AgeBandEnum ageBand(@Nullable Owner owner) {
79	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
80	            return null;
81	        }
82	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
83	        if (age < 18) {
84	            return OwnerDto.AgeBandEnum.MINOR;
85	        }
86	        if (age < 65) {
87	            return OwnerDto.AgeBandEnum.ADULT;
88	        }
89	        return OwnerDto.AgeBandEnum.SENIOR;
90	    }
91	
92	    /**
93	     * Derives the owner's duplicate-detection {@code identityKey}: the lower-case hex SHA-256 of
94	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}, with an empty segment
95	     * for an absent telephone or email. This is the same key the create endpoint uses to reject an
96	     * owner whose whole key equals an existing owner's.
97	     */
98	    default @Nullable String identityKey(@Nullable Owner owner) {
99	        if (owner == null) {
100	            return null;
101	        }
102	        return org.springframework.samples.petclinic.util.IdentityKeys.identityKey(
103	            owner.getTelephone(), owner.getEmail(), owner.getLastName());
104	    }
105	
106	    /**
107	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
108	     * otherwise {@code PHONE}.
109	     */
110	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
111	        if (owner == null) {
112	            return null;
113	        }
114	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
115	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
116	    }
117	
118	    /**
119	     * Derives the owner's locality from its region-and-hash identity: the {@code REGION} prefix of
120	     * the {@code customerCode} ({@code '<REGION>-<HASH8>'}), which is the region code derived from
121	     * the postcode on create. Returns the canonical region string, or {@code 'UNKNOWN'} when the
122	     * owner has no customerCode.
123	     */
124	    default @Nullable String locality(@Nullable Owner owner) {
125	        if (owner == null) {
126	            return null;
127	        }
128	        String customerCode = owner.getCustomerCode();
129	        if (customerCode == null) {
130	            return "UNKNOWN";
131	        }
132	        int dash = customerCode.indexOf('-');
133	        return dash < 0 ? "UNKNOWN" : customerCode.substring(0, dash);
134	    }
135	
136	    /**
137	     * Derives the owner's {@code timezone} as an IANA name from its locality/region using the fixed
138	     * region-to-timezone table: {@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
139	     * and {@code QLD -> Australia/Brisbane}. Returns {@code null} when the region is not in the table.
140	     */
141	    default @Nullable String timezone(@Nullable Owner owner) {
142	        String region = locality(owner);
143	        if (region == null) {
144	            return null;
145	        }
146	        return switch (region) {
147	            case "NSW" -> "Australia/Sydney";
148	            case "VIC" -> "Australia/Melbourne";
149	            case "QLD" -> "Australia/Brisbane";
150	            default -> null;
151	        };
152	    }
153	
154	    /**
155	     * Returns the owner's membership points. Starting at 0, it adds 2 when an email is present, 1
156	     * when namesakeCount is 0, 2 when the owner belongs to a household of at least 3 members, and 3
157	     * when tenure spans at least one elapsed fiscal year since the registrationDate (the fiscal year
158	     * starts on 1 July). Because a newly created owner shares the current fiscal year it never earns
159	     * the tenure points.
160	     */
161	    default @Nullable Integer membershipPoints(@Nullable Owner owner) {
162	        if (owner == null) {
163	            return null;
164	        }
165	        int points = 0;
166	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
167	        if (hasEmail) {
168	            points += 2;
169	        }
170	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
171	        if (noNamesakes) {
172	            points += 1;
173	        }
174	        boolean largeHousehold = owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
175	        if (largeHousehold) {
176	            points += 2;
177	        }
178	        if (hasQualifyingTenure(owner)) {
179	            points += 3;
180	        }
181	        return points;
182	    }
183	
184	    /**
185	     * Returns the owner's numeric membership level. When a membership level has been persisted on the
186	     * owner (the household-capped value assigned on create) that stored value is returned; otherwise the
187	     * level is derived from membershipPoints via {@link #derivedMembershipLevel(Owner)}.
188	     */
189	    default @Nullable Integer membershipLevel(@Nullable Owner owner) {
190	        if (owner != null && owner.getMembershipLevel() != null) {
191	            return owner.getMembershipLevel();
192	        }
193	        return derivedMembershipLevel(owner);
194	    }
195	
196	    /**
197	     * Derives the owner's numeric membership level from 1 to 4 from membershipPoints, ignoring any
198	     * stored value: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more points.
199	     */
200	    default @Nullable Integer derivedMembershipLevel(@Nullable Owner owner) {
201	        Integer points = membershipPoints(owner);
202	        if (points == null) {
203	            return null;
204	        }
205	        if (points <= 1) {
206	            return 1;
207	        }
208	        if (points <= 3) {
209	            return 2;
210	        }
211	        if (points <= 5) {
212	            return 3;
213	        }
214	        return 4;
215	    }
216	
217	    /**
218	     * Whether the owner's tenure spans at least one elapsed fiscal year, i.e. the current fiscal year
219	     * is later than the fiscal year of its registrationDate (the fiscal year starts on 1 July).
220	     * Returns {@code false} when the registrationDate is absent (or in the future, which shares the
221	     * current fiscal year), so a newly created owner has no qualifying tenure.
222	     */
223	    default boolean hasQualifyingTenure(@Nullable Owner owner) {
224	        if (owner == null || owner.getRegistrationDate() == null) {
225	            return false;
226	        }
227	        int elapsedFiscalYears = fiscalYearEnding(java.time.LocalDate.now())
228	            - fiscalYearEnding(owner.getRegistrationDate());
229	        return elapsedFiscalYears >= 1;
230	    }
231	
232	    /**
233	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
234	     * digits of the fiscal year (ending) derived from the business-day-adjusted registrationDate, e.g.
235	     * {@code 'MEL-SMI-0007-M26'}.
236	     */
237	    default @Nullable String membershipNumber(@Nullable Owner owner) {
238	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
239	            return null;
240	        }
241	        return String.format("%s-M%02d", owner.getCustomerCode(), fiscalYearEnding(owner.getRegistrationDate()) % 100);
242	    }
243	
244	    /**
245	     * Returns the Luhn check digit (0-9) computed over the digits contained in the owner's
246	     * customerCode, or {@code null} when the owner or its customerCode is absent.
247	     */
248	    default @Nullable Integer checkDigit(@Nullable Owner owner) {
249	        if (owner == null || owner.getCustomerCode() == null) {
250	            return null;
251	        }
252	        String s = owner.getCustomerCode();
253	        int sum = 0;
254	        boolean dbl = true;
255	        for (int i = s.length() - 1; i >= 0; i--) {
256	            char c = s.charAt(i);
257	            if (c < '0' || c > '9') {
258	                continue;
259	            }
260	            int d = c - '0';
261	            if (dbl) {
262	                d *= 2;
263	                if (d > 9) {
264	                    d -= 9;
265	                }
266	            }
267	            sum += d;
268	            dbl = !dbl;
269	        }
270	        return (10 - (sum % 10)) % 10;
271	    }
272	
273	    /**
274	     * Formats the owner's stored E.164 {@code telephone} for humans: the country code, a space, then
275	     * the national digits grouped in threes separated by spaces, e.g. {@code '+61 412 345 678'} for a
276	     * stored {@code '+61412345678'}. The country code is the single digit for the {@code +1} and
277	     * {@code +7} plans and two digits otherwise. Returns the raw value unchanged when it is not a
278	     * {@code '+'}-prefixed digit string, or {@code null} when absent.
279	     */
280	    default @Nullable String telephoneDisplay(@Nullable Owner owner) {
281	        if (owner == null) {
282	            return null;
283	        }
284	        String telephone = owner.getTelephone();
285	        if (telephone == null || !telephone.matches("\\+\\d+")) {
286	            return telephone;
287	        }
288	        String digits = telephone.substring(1);
289	        int countryCodeLength = (digits.startsWith("1") || digits.startsWith("7")) ? 1 : 2;
290	        countryCodeLength = Math.min(countryCodeLength, digits.length());
291	        String countryCode = digits.substring(0, countryCodeLength);
292	        String national = digits.substring(countryCodeLength);
293	        StringBuilder sb = new StringBuilder("+").append(countryCode);
294	        for (int i = 0; i < national.length(); i += 3) {
295	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
296	        }
297	        return sb.toString();
298	    }
299	
300	    /**
301	     * Composes the owner's salutation as {@code 'title lastName'} when a title is present,
302	     * or just the {@code lastName} when no title is given.
303	     */
304	    default @Nullable String salutation(@Nullable Owner owner) {
305	        if (owner == null) {
306	            return null;
307	        }
308	        String title = owner.getTitle();
309	        if (title == null || title.isEmpty()) {
310	            return owner.getLastName();
311	        }
312	        return title + " " + owner.getLastName();
313	    }
314	
315	    /**
316	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
317	     */
318	    default @Nullable String displayName(@Nullable Owner owner) {
319	        if (owner == null) {
320	            return null;
321	        }
322	        return owner.getLastName() + ", " + owner.getFirstName();
323	    }
324	
325	    /**
326	     * Formats an owner's initials as the upper-cased first letters of firstName and
327	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
328	     */
329	    default @Nullable String initials(@Nullable Owner owner) {
330	        if (owner == null) {
331	            return null;
332	        }
333	        StringBuilder sb = new StringBuilder();
334	        String firstName = owner.getFirstName();
335	        if (firstName != null && !firstName.isEmpty()) {
336	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
337	        }
338	        String lastName = owner.getLastName();
339	        if (lastName != null && !lastName.isEmpty()) {
340	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
341	        }
342	        return sb.toString();
343	    }
